<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Sistema de Reservas de Hotel</title>
  <link rel="stylesheet" href="/styles.css" />
</head>
<body>
  <header class="topbar">
    <div class="brand">
      <span class="logo">🏨</span>
      <div>
        <strong>Hotel Reserva Fácil</strong>
        <small>Sistema completo de reservas</small>
      </div>
    </div>

    <nav id="nav" class="nav"></nav>
  </header>

  <main class="container">
    <section id="authView" class="view">
      <div class="hero">
        <div>
          <h1>Reserve quartos de hotel com segurança</h1>
          <p>Entre na sua conta para consultar disponibilidade, reservar quartos e acompanhar suas reservas.</p>
        </div>
      </div>

      <div class="auth-grid">
        <form id="loginForm" class="card">
          <h2>Entrar</h2>
          <label>
            E-mail
            <input type="email" name="email" required placeholder="seu@email.com" />
          </label>
          <label>
            Senha
            <input type="password" name="password" required placeholder="Sua senha" />
          </label>
          <button type="submit">Entrar</button>
          <p class="hint">Gerente inicial: gerente@hotel.com / gerente123</p>
        </form>

        <form id="registerForm" class="card">
          <h2>Criar conta de hóspede</h2>
          <label>
            Nome
            <input type="text" name="name" required placeholder="Seu nome" />
          </label>
          <label>
            E-mail
            <input type="email" name="email" required placeholder="seu@email.com" />
          </label>
          <label>
            Senha
            <input type="password" name="password" required minlength="6" placeholder="Mínimo 6 caracteres" />
          </label>
          <button type="submit">Criar conta</button>
        </form>
      </div>
    </section>

    <section id="guestView" class="view hidden">
      <div class="section-title">
        <div>
          <h1>Área do hóspede</h1>
          <p>Escolha as datas para ver quartos disponíveis.</p>
        </div>
      </div>

      <form id="searchForm" class="card search">
        <label>
          Entrada
          <input type="date" name="checkin" required />
        </label>
        <label>
          Saída
          <input type="date" name="checkout" required />
        </label>
        <label>
          Hóspedes
          <input type="number" name="guests" min="1" value="1" required />
        </label>
        <button type="submit">Buscar quartos</button>
      </form>

      <div class="split">
        <div>
          <h2>Quartos disponíveis</h2>
          <div id="availableRooms" class="cards"></div>
        </div>

        <div>
          <h2>Minhas reservas</h2>
          <div id="myReservations" class="cards"></div>
        </div>
      </div>
    </section>

    <section id="managerView" class="view hidden">
      <div class="section-title">
        <div>
          <h1>Área do gerente</h1>
          <p>Gerencie quartos e reservas do hotel.</p>
        </div>
      </div>

      <div class="split">
        <div>
          <form id="roomForm" class="card">
            <h2 id="roomFormTitle">Cadastrar quarto</h2>
            <input type="hidden" name="id" />
            <label>
              Nome
              <input type="text" name="name" required placeholder="Ex.: Quarto Standard" />
            </label>
            <label>
              Descrição
              <textarea name="description" required placeholder="Descreva o quarto"></textarea>
            </label>
            <label>
              Capacidade
              <input type="number" name="capacity" min="1" required />
            </label>
            <label>
              Preço por diária
              <input type="number" name="price" min="0" step="0.01" required />
            </label>
            <label>
              Imagem URL
              <input type="url" name="image" placeholder="https://..." />
            </label>
            <label class="check">
              <input type="checkbox" name="active" checked />
              Quarto ativo
            </label>
            <div class="row">
              <button type="submit">Salvar quarto</button>
              <button type="button" id="cancelEditRoom" class="secondary hidden">Cancelar edição</button>
            </div>
          </form>

          <h2>Quartos cadastrados</h2>
          <div id="managerRooms" class="cards"></div>
        </div>

        <div>
          <h2>Todas as reservas</h2>
          <div id="managerReservations" class="cards"></div>
        </div>
      </div>
    </section>
  </main>

  <div id="toast" class="toast hidden"></div>

  <script src="/app.js"></script>
</body>
</html>

