* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f3f6fb;
  color: #1d2939;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  background: #ffffff;
  border-bottom: 1px solid #d9e2ec;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 22px;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo {
  font-size: 34px;
}

.brand small {
  display: block;
  color: #667085;
  font-size: 12px;
}

.nav {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.container {
  width: min(1180px, calc(100% - 28px));
  margin: 24px auto 60px;
}

.hero {
  background: linear-gradient(135deg, #0f4c81, #2094d8);
  color: white;
  padding: 32px;
  border-radius: 18px;
  margin-bottom: 20px;
}

.hero h1 {
  margin: 0 0 8px;
  font-size: clamp(28px, 4vw, 44px);
}

.hero p {
  margin: 0;
  font-size: 18px;
  max-width: 700px;
}

.auth-grid,
.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.card {
  background: white;
  border: 1px solid #d9e2ec;
  border-radius: 16px;
  padding: 18px;
  box-shadow: 0 8px 24px rgba(16, 24, 40, 0.06);
}

.card h2,
.section-title h1,
.section-title p {
  margin-top: 0;
}

.section-title {
